window.AUTH=window.AUTH||{};window.AUTH["06-1321"]={"d":"06-1321","id":"2007/06-1321","n":"Gómez-Pérez v. Potter","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the respondent","date":"","url":"https://www.justice.gov/osg/media/200696/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/gomez-perez-v-potter-brief-merits","n":116}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep553/usrep553474/usrep553474.pdf","tr":true,"items":[{"t":"case","label":"Ayon v. Sampson","cite":"547 F.2d 446","y":1976,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/547/446/","by":{"0":"39"}},{"t":"case","label":"Bornholdt v. Brady","cite":"869 F.2d 57","y":1989,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/869/57/","sum":"Recognizing retaliation cause of action for federal employees under ADEA.","sumSrc":"brief:0","by":{"0":"43"}},{"t":"case","label":"Burlington N. & Santa Fe Ry. v. White","cite":"126 S. Ct. 2405","y":2006,"id":"2005/05-259","sc":1,"op":8,"ar":1,"sum":"In a decision authored by Justice Stephen Breyer and joined by Chief Justice Roberts and six other justices, the Court held that in order to prevail on a claim of retaliatory discrimination, \"a plaintiff must show that a reasonable employee would have found the challenged action materially adverse, which in this context means it well might have dissuaded a reasonable worker from making or supporting a charge of discrimination.\" (internal citations omitted) Justice Samuel Alito wrote separately, agreeing with the result but arguing that the test adopted by the other members of the Court would eventually prove problematic.","sumSrc":"Oyez","by":{"0":"6, 15, 16, 17, 18"}},{"t":"case","label":"Bush v. Lucas","cite":"462 U.S. 367","y":1983,"id":"1982/81-469","sc":1,"op":2,"ar":2,"sum":"Not under the CSC regulations. The federal judiciary, pursuant to its common law authority, has the power to recognize new causes of action in absence of, or to supplement, statutory remedies unless Congress has expressly indicated its relief is to be exclusive.","sumSrc":"Oyez","by":{"0":"27, 28, 29, 35, 45"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Deal v. United States","cite":"508 U.S. 129","y":1993,"id":"1992/91-8199","sc":1,"sum":"The Court held that Deal's second through sixth convictions in a single proceeding arose \"in the case of his second or subsequent conviction\" within the meaning of section 924(c)(1), finding that the statute was not ambiguous.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs. Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"sum":"The Court ruled that as long one plaintiff meets the amount-in-controversy requirement for federal jurisdiction, Section 1367 authorizes federal courts to exercise supplemental jurisdiction over related claims even if they do not meet the requirement.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Frommhagen v. Klein","cite":"456 F.2d 1391","y":1972,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/456/1391/","by":{"0":"31"}},{"t":"case","label":"Gebser v. Lago Vista Indep. Sch. Dist.","cite":"524 U.S. 274","y":1998,"id":"1997/96-1866","sc":1,"sum":"In a 5-to-4 decision the Court held that two minimal criteria must be met in order for an aggrieved party to recover sexual harassment damages under the Amendments. First, the party must show that a school district official, with the ability to institute corrective measures, knew of the forbidden conduct.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"George v. Leavitt","cite":"407 F.3d 405","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/407/405/","by":{"0":"16"}},{"t":"case","label":"Goodyear Atomic Corp. v. Miller","cite":"486 U.S. 174","y":1988,"id":"1987/86-1172","sc":1,"sum":"Appellee Miller, an employee of appellant at an Ohio nuclear production facility owned by the United States but operated by appellant, a private contractor, received a workers' compensation award from appellee Ohio Industrial Commission (Commission) for injuries sustained in a fall allegedly caused by a bolt protruding from the scaffold on which he was working. On the basis of a state safety regulation prohibiting …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Hale v. Marsh","cite":"808 F.2d 616","y":1986,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/808/616/","sum":"Recognizing retaliation cause of action for federal employees under Title VII.","sumSrc":"brief:0","by":{"0":"39, 43"}},{"t":"case","label":"Harrell v. USPS","cite":"445 F.3d 913","y":2006,"url":"https://www.courtlistener.com/c/F.3d/445/913/","by":{"0":"37"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Irwin v. Department of Veterans Affairs","cite":"498 U.S. 89","y":1990,"id":"1990/89-5867","sc":1,"sum":"The Supreme Court held that lower courts have consistently held that notice to an attorney's office qualifies as notice to the client. \"The practical effect of a contrary rule would be to encourage factual disputes about when actual notice was received, and thereby create uncertainty in an area of the law where certainty is much to be desired,\" wrote Chief Justice Rehnquist.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Jackson v. Birmingham Bd. of Educ.","cite":"544 U.S. 167","y":2005,"id":"2004/02-1672","sc":1,"op":17,"sum":"The Court held that Title IX allowed suits alleging retaliation for reporting sex discrimination. Such retaliation, the majority reasoned, constituted intentional discrimination on the basis of sex in violation of Title IX. Jackson therefore had the right under Title IX to pursue his claim in court.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Johnson v. Railway Express Agency, Inc.","cite":"421 U.S. 454","y":1975,"id":"1974/73-1543","sc":1,"sum":"The timely filing of an employment discrimination charge with the Equal Employment Opportunity Commission, pursuant to § 706 of Title VII of the Civil Rights Act of 1964, does not toll the running of the limitation period applicable to an action, based on the same facts, brought under 42 U. S. C. § 1981. Thus, in this case where petitioner waited over 31/2 years after his cause of action for racial employment …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Lane v. Pena","cite":"518 U.S. 187","y":1996,"id":"1995/95-365","sc":1,"op":2,"sum":"Although the related provisions of the 1973 Rehabilitation Act and the 1991 Civil Rights Act might in combination be read as waiving the federal government's sovereign immunity, absent an unambiguous waiver of sovereign immunity, the court cannot permit damages to be awarded.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Lehman v. Nakshian","cite":"453 U.S. 156","y":1981,"id":"1980/80-242","sc":1,"op":4,"ar":3,"sum":"Respondent was not entitled to a jury trial.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Lindahl v. OPM","cite":"470 U.S. 768","y":1985,"id":"1984/83-5954","sc":1,"sum":"The Office of Personnel Management (OPM) \"determine[s] questions of disability and dependency\" in administering the Federal Government's disability retirement program. 5 U. S. C. § 8347(c). Its \"decisions... concerning these matters are final and conclusive and are not subject to review,\" ibid., except to the extent that administrative review by the Merit Systems Protection Board (MSPB) is provided by §8347(d)(1). …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"McMahon v. United States","cite":"342 U.S. 25","y":1951,"id":"scdb/1951-003","sc":1,"sum":"The period of limitation begins to run from the date of the injury, not from the time of the administrative disallowance of the claim.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Page v. Bolger","cite":"645 F.2d 227","y":1981,"url":"https://www.courtlistener.com/c/F.2d/645/227/","by":{"0":"16"}},{"t":"case","label":"Predmore v. Allen","cite":"407 F. Supp. 1067","y":1976,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp./407/1067/","by":{"0":"31"}},{"t":"case","label":"Richards v. United States","cite":"369 U.S. 1","y":1962,"id":"1961/59","sc":1,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Ruckelshaus v. Sierra Club","cite":"463 U.S. 680","y":1983,"id":"1982/82-242","sc":1,"sum":"Absent some degree of success on the merits by the claimant, it is not \"appropriate\" for a federal court to award attorney's fees under §307(f).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"op":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 17, 22"}},{"t":"case","label":"Smith v. City of Jackson","cite":"544 U.S. 228","y":2005,"id":"2004/03-1160","sc":1,"op":13,"sum":"The Court held that ADEA authorized recovery in disparate-impact cases, but that in this case petitioners failed to set forth a valid claim. The Court relied on its 1971 decision in Griggs v. Duke Power, where the Court first authorized disparate-impact claims brought under Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"0":"11, 38"}},{"t":"case","label":"Sullivan v. Little Hunting Park, Inc.","cite":"396 U.S. 229","y":1969,"id":"1969/33","sc":1,"op":36,"sum":"Little Hunting Park is a Virginia nonstock corporation operating playground facilities and a community park for residents in an area in Fairfax County, Virginia. A membership share entitles a shareholder and his family to use its facilities, and under the bylaws when he rents his house he may assign the share to his tenant, subject to approval by the board of directors. The facilities have been open to any white …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8, 20, 22"}},{"t":"case","label":"Textron Lycoming Reciprocating Engine Div., Avco Corp. v. UAW","cite":"523 U.S. 653","y":1998,"id":"1997/97-463","sc":1,"sum":"The Court held that neither it nor the lower federal courts have subject-matter jurisdiction under section 301 because the Union's complaint alleged no violation of the collective-bargaining agreement. \"Suits for violation of contracts\" under [section 301(a)] are not suits that claim a contract is invalid, but suits that claim a contract has been violated, wrote Justice Scalia.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Tillman v. Wheaton-Haven Recreation Ass’n","cite":"410 U.S. 431","y":1973,"id":"1972/71-1136","sc":1,"sum":"Respondent association (Wheaton-Haven) operates a community swimming pool, use of which is limited to white members and their white guests. Under Wheaton-Haven's bylaws, a person residing within a geographic preference area, unlike one living outside that area, needs no endorsement for membership from a current member; receives priority (if the membership is full) over all but those who have first options; and (if …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"op":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31, 35"}},{"t":"case","label":"United States v. King","cite":"395 U.S. 1","y":1969,"id":"1968/672","sc":1,"sum":"The jurisdiction of the Court of Claims is limited to money claims against the United States and that court does not have the authority to issue declaratory judgments. Pp. 2-5. 182 Ct. Cl. 631, 390 F. 2d 894, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"United States v. Mitchell","cite":"445 U.S. 535","y":1980,"id":"1979/78-1756","sc":1,"sum":"The General Allotment Act cannot be read as establishing that the United States has a fiduciary responsibility for management of allotted forest lands, and thus does not provide respondents with a cause of action for the damages sought.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"United States v. Navajo Nation","cite":"537 U.S. 488","y":2003,"id":"2002/01-1375","sc":1,"sum":"The Court ruled that an Indian Tribe must \"identify a substantive source of law that establishes specific fiduciary or other duties.\" The opinion by Justice Ruth Bader Ginsburg held that the IMLA could not be interpreted to require the Secretary to exercise broad authority to manage the tribe's resources for the tribe's benefit.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Case—Continued: United States v. Nordic Vill., Inc.","cite":"503 U.S. 30","y":1992,"id":"1991/90-1629","sc":1,"op":1,"ar":1,"sum":"After respondent Nordic Village, Inc., filed a petition for relief under Chapter 11 of the Bankruptcy Code, one of its officers withdrew funds from the company's corporate account. He sent part of the money to the Internal Revenue Service (IRS), directing it to apply the funds against his individual tax liability, which it did. In a subsequent adversary proceeding, the Bankruptcy Court permitted Nordic Village's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44, 45, 46"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"27"}},{"t":"law","label":"Pub. L. No. 95-256","url":"https://www.govinfo.gov/link/statute/92/192","by":{"0":"24"}},{"t":"law","label":"Pub. L. No. 90-202","url":"https://www.govinfo.gov/link/statute/81/605","by":{"0":"2"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","stext":{"head":"§621. Congressional statement of findings and purpose","paras":[[0,"(a) The Congress hereby finds and declares that—"],[1,"(1) in the face of rising productivity and affluence, older workers find themselves disadvantaged in their efforts to retain employment, and especially to regain employment when displaced from jobs;"],[1,"(2) the setting of arbitrary age limits regardless of potential for job performance has become a common practice, and certain otherwise desirable practices may work to the disadvantage of older persons;"],[1,"(3) the incidence of unemployment, especially long-term unemployment with resultant deterioration of skill, morale, and employer acceptability is, relative to the younger ages, high among older workers; their numbers are great and growing; and their employment problems grave;"],[1,"(4) the existence in industries affecting commerce, of arbitrary discrimination in employment because of age, burdens commerce and the free flow of goods in commerce."],[0,"(b) It is therefore the purpose of this chapter to promote employment of older persons based on their ability rather than age; to prohibit arbitrary age discrimination in employment; to help employers and workers find ways of meeting problems arising from the impact of age on employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/621?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§621. Congressional statement of findings and purpose","tname":"Labor","by":{"0":"1"}},{"t":"usc","label":"29 U.S.C. § 623","url":"https://www.law.cornell.edu/uscode/text/29/623","subs":["(a)","(a)(1)","(b)","(c)(1)","(d)"],"stext":{"head":"§623. Prohibition of age discrimination","paras":[[0,"(a) Employer practices"],[0,"It shall be unlawful for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual or otherwise discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's age;"],[1,"(2) to limit, segregate, or classify his employees in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's age; or"],[1,"(3) to reduce the wage rate of any employee in order to comply with this chapter."],[0,"(b) Employment agency practices"],[0,"It shall be unlawful for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of such individual's age, or to classify or refer for employment any individual on the basis of such individual's age."],[0,"(c) Labor organization practices"],[0,"It shall be unlawful for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his age;"],[1,"(2) to limit, segregate, or classify its membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's age;"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Opposition to unlawful practices; participation in investigations, proceedings, or litigation"],[0,"It shall be unlawful for an employer to discriminate against any of his employees or applicants for employment, for an employment agency to discriminate against any individual, or for a labor organization to discriminate against any member thereof or applicant for membership, because such individual, member or applicant for membership has opposed any practice made unlawful by this section, or because such individual, member or applicant for membership has made a charge, testified, assisted, or participated in any manner in an investigation, proceeding, or litigation under this chapter."],[0,"(e) Printing or publication of notice or advertisement indicating preference, limitation, etc."],[0,"It shall be unlawful for an employer, labor organization, or employment agency to print or publish, or cause to be printed or published, any notice or advertisement relating to employment by such an employer or membership in or any classification or referral for employment by such a labor organization, or relating to any classification or referral for employment by such an employment agency, indicating any preference, limitation, specification, or discrimination, based on age."],[0,"(f) Lawful practices; age an occupational qualification; other reasonable factors; laws of foreign workplace; seniority system; employee benefit plans; discharge or discipline for good cause"],[0,"It shall not be unlawful for an employer, employment agency, or labor organization—"],[1,"(1) to take any action otherwise prohibited under subsections (a), (b), (c), or (e) of this section where age is a bona fide occupational qualification reasonably necessary to the normal operation of the particular business, or where the differentiation is based on reasonable factors other than age, or where such practices involve an employee in a workplace in a foreign country, and compliance with such subsections would cause such employer, or a corporation controlled by such employer, to violate the laws of the country in which such workplace is located;"],[1,"(2) to take any action otherwise prohibited under subsection (a), (b), (c), or (e) of this section—"],[2,"(A) to observe the terms of a bona fide seniority system that is not intended to evade the purposes of this chapter, except that no such seniority system shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title because of the age of such individual; or"],[2,"(B) to observe the terms of a bona fide employee benefit plan—"],[3,"(i) where, for each benefit or benefit package, the actual amount of payment made or cost incurred on behalf of an older worker is no less than that made or incurred on behalf of a younger worker, as permissible under section 1625.10, title 29, Code of Federal Regulations (as in effect on June 22, 1989); or"],[3,"(ii) that is a voluntary early retirement incentive plan consistent with the relevant purpose or purposes of this chapter."],[1,"Notwithstanding clause (i) or (ii) of subparagraph (B), no such employee benefit plan or voluntary early retirement incentive plan shall excuse the failure to hire any individual, and no such employee benefit plan shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title, because of the age of such individual. An employer, employment agency, or labor organization acting under subparagraph (A), or under clause (i) or (ii) of subparagraph (B), shall have the burden of proving that such actions are lawful in any civil enforcement proceeding brought under this chapter; or"],[1,"(3) to discharge or otherwise discipline an individual for good cause."],[0,"(g) Repealed. Pub. L. 101–239, title VI, §6202(b)(3)(C)(i), Dec. 19, 1989, 103 Stat. 2233"],[0,"(h) Practices of foreign corporations controlled by American employers; foreign employers not controlled by American employers; factors determining control"],[0,"(1) If an employer controls a corporation whose place of incorporation is in a foreign country, any practice by such corporation prohibited under this section shall be presumed to be such practice by such employer."],[0,"(2) The prohibitions of this section shall not apply where the employer is a foreign person not controlled by an American employer."],[0,"(3) For the purpose of this subsection the determination of whether an employer controls a corporation shall be based upon the—"],[1,"(A) interrelation of operations,"],[1,"(B) common management,"],[1,"(C) centralized control of labor relations, and"],[1,"(D) common ownership or financial control,"],[0,"of the employer and the corporation."],[0,"(i) Employee pension benefit plans; cessation or reduction of benefit accrual or of allocation to employee account; distribution of benefits after attainment of normal retirement age; compliance; highly compensated employees"],[0,"(1) Except as otherwise provided in this subsection, it shall be unlawful for an employer, an employment agency, a labor organization, or any combination thereof to establish or maintain an employee pension benefit plan which requires or permits—"],[1,"(A) in the case of a defined benefit plan, the cessation of an employee's benefit accrual, or the reduction of the rate of an employee's benefit accrual, because of age, or"],[1,"(B) in the case of a defined contribution plan, the cessation of allocations to an employee's account, or the reduction of the rate at which amounts are allocated to an employee's account, because of age."],[0,"(2) Nothing in this section shall be construed to prohibit an employer, employment agency, or labor organization from observing any provision of an employee pension benefit plan to the extent that such provision imposes (without regard to age) a limitation on the amount of benefits that the plan provides or a limitation on the number of years of service or years of participation which are taken into account for purposes of determining benefit accrual under the plan."],[0,"(3) In the case of any employee who, as of the end of any plan year under a defined benefit plan, has attained normal retirement age under such plan—"],[1,"(A) if distribution of benefits under such plan with respect to such employee has commenced as of the end of such plan year, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of the actuarial equivalent of in-service distribution of benefits, and"],[1,"(B) if distribution of benefits under such plan with respect to such employee has not commenced as of the end of such year in accordance with section 1056(a)(3) of this title and section 401(a)(14)(C) of title 26, and the payment of benefits under such plan with respect to such employee is not suspended during such plan year pursuant to section 1053(a)(3)(B) of this title or section 411(a)(3)(B) of title 26, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of any adjustment in the benefit payable under the plan during such plan year attributable to the delay in the distribution of benefits after the attainment of normal retirement age."],[0,"The provisions of this paragraph shall apply in accordance with regulations of the Secretary of the Treasury. Such regulations shall provide for the application of the preceding provisions of this paragraph to all employee pension benefit plans subject to this subsection and may provide for the application of such provisions, in the case of any such employee, with respect to any period of time within a plan year."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/623?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§623. Prohibition of age discrimination","tname":"Labor","by":{"0":"1, 2, 10, 17, 24, 18, 1, 10, 18, 23, 23, 23, passim"}},{"t":"usc","label":"29 U.S.C. § 630","url":"https://www.law.cornell.edu/uscode/text/29/630","subs":["(b)"],"stext":{"head":"§630. Definitions","paras":[[0,"For the purposes of this chapter—"],[0,"(a) The term \"person\" means one or more individuals, partnerships, associations, labor organizations, corporations, business trusts, legal representatives, or any organized groups of persons."],[0,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has twenty or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year: Provided, That prior to June 30, 1968, employers having fewer than fifty employees shall not be considered employers. The term also means (1) any agent of such a person, and (2) a State or political subdivision of a State and any agency or instrumentality of a State or a political subdivision of a State, and any interstate agency, but such term does not include the United States, or a corporation wholly owned by the Government of the United States."],[0,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer and includes an agent of such a person; but shall not include an agency of the United States."],[0,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[0,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is fifty or more prior to July 1, 1968, or twenty-five or more on or after July 1, 1968, and such labor organization—"],[1,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.]; or"],[1,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[1,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[1,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[1,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[0,"(f) The term \"employee\" means an individual employed by any employer except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policymaking level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency, or political subdivision. The term \"employee\" includes any individual who is a citizen of the United States employed by an employer in a workplace in a foreign country."],[0,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[0,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.]."],[0,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[0,"(j) The term \"firefighter\" means an employee, the duties of whose position are primarily to perform work directly connected with the control and extinguishment of fires or the maintenance and use of firefighting apparatus and equipment, including an employee engaged in this activity who is transferred to a supervisory or administrative position."],[0,"(k) The term \"law enforcement officer\" means an employee, the duties of whose position are primarily the investigation, apprehension, or detention of individuals suspected or convicted of offenses against the criminal laws of a State, including an employee engaged in this activity who is transferred to a supervisory or administrative position. For the purpose of this subsection, \"detention\" includes the duties of employees assigned to guard individuals incarcerated in any penal institution."],[0,"(l) The term \"compensation, terms, conditions, or privileges of employment\" encompasses all employee benefits, including such benefits provided pursuant to a bona fide employee benefit plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/630?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§630. Definitions","tname":"Labor","by":{"0":"2"}},{"t":"usc","label":"29 U.S.C. § 631","url":"https://www.law.cornell.edu/uscode/text/29/631","subs":["(b)"],"by":{"0":"3, 15, 26"}},{"t":"usc","label":"29 U.S.C. § 633a","url":"https://www.law.cornell.edu/uscode/text/29/633a","subs":["(a)","(b)","(b)(3)","(c)","(d)","(f)"],"stext":{"head":"§633a. Nondiscrimination on account of age in Federal Government employment","paras":[[0,"(a) Federal agencies affected"],[0,"All personnel actions affecting employees or applicants for employment who are at least 40 years of age (except personnel actions with regard to aliens employed outside the limits of the United States) in military departments as defined in section 102 of title 5, in executive agencies as defined in section 105 of title 5 (including employees and applicants for employment who are paid from nonappropriated funds), in the United States Postal Service and the Postal Regulatory Commission, in those units in the government of the District of Columbia having positions in the competitive service, and in those units of the judicial branch of the Federal Government having positions in the competitive service, in the Smithsonian Institution, and in the Government Publishing Office, the Government Accountability Office, and the Library of Congress shall be made free from any discrimination based on age."],[0,"(b) Enforcement by Equal Employment Opportunity Commission and by Librarian of Congress in the Library of Congress; remedies; rules, regulations, orders, and instructions of Commission: compliance by Federal agencies; powers and duties of Commission; notification of final action on complaint of discrimination; exemptions: bona fide occupational qualification"],[0,"Except as otherwise provided in this subsection, the Equal Employment Opportunity Commission is authorized to enforce the provisions of subsection (a) through appropriate remedies, including reinstatement or hiring of employees with or without backpay, as will effectuate the policies of this section. The Equal Employment Opportunity Commission shall issue such rules, regulations, orders, and instructions as it deems necessary and appropriate to carry out its responsibilities under this section. The Equal Employment Opportunity Commission shall—"],[1,"(1) be responsible for the review and evaluation of the operation of all agency programs designed to carry out the policy of this section, periodically obtaining and publishing (on at least a semiannual basis) progress reports from each department, agency, or unit referred to in subsection (a);"],[1,"(2) consult with and solicit the recommendations of interested individuals, groups, and organizations relating to nondiscrimination in employment on account of age; and"],[1,"(3) provide for the acceptance and processing of complaints of discrimination in Federal employment on account of age."],[0,"The head of each such department, agency, or unit shall comply with such rules, regulations, orders, and instructions of the Equal Employment Opportunity Commission which shall include a provision that an employee or applicant for employment shall be notified of any final action taken on any complaint of discrimination filed by him thereunder. Reasonable exemptions to the provisions of this section may be established by the Commission but only when the Commission has established a maximum age requirement on the basis of a determination that age is a bona fide occupational qualification necessary to the performance of the duties of the position. With respect to employment in the Library of Congress, authorities granted in this subsection to the Equal Employment Opportunity Commission shall be exercised by the Librarian of Congress."],[0,"(c) Civil actions; jurisdiction; relief"],[0,"Any person aggrieved may bring a civil action in any Federal district court of competent jurisdiction for such legal or equitable relief as will effectuate the purposes of this chapter."],[0,"(d) Notice to Commission; time of notice; Commission notification of prospective defendants; Commission elimination of unlawful practices"],[0,"When the individual has not filed a complaint concerning age discrimination with the Commission, no civil action may be commenced by any individual under this section until the individual has given the Commission not less than thirty days' notice of an intent to file such action. Such notice shall be filed within one hundred and eighty days after the alleged unlawful practice occurred. Upon receiving a notice of intent to sue, the Commission shall promptly notify all persons named therein as prospective defendants in the action and take any appropriate action to assure the elimination of any unlawful practice."],[0,"(e) Duty of Government agency or official"],[0,"Nothing contained in this section shall relieve any Government agency or official of the responsibility to assure nondiscrimination on account of age in employment as required under any provision of Federal law."],[0,"(f) Applicability of statutory provisions to personnel action of Federal departments, etc."],[0,"Any personnel action of any department, agency, or other entity referred to in subsection (a) of this section shall not be subject to, or affected by, any provision of this chapter, other than the provisions of sections 626(d)(3) and 631(b) of this title and the provisions of this section."],[0,"(g) Study and report to President and Congress by Equal Employment Opportunity Commission; scope"],[0,"(1) The Equal Employment Opportunity Commission shall undertake a study relating to the effects of the amendments made to this section by the Age Discrimination in Employment Act Amendments of 1978, and the effects of section 631(b) of this title."],[0,"(2) The Equal Employment Opportunity Commission shall transmit a report to the President and to the Congress containing the findings of the Commission resulting from the study of the Commission under paragraph (1) of this subsection. Such report shall be transmitted no later than January 1, 1980."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/633a?type=usc&year=mostrecent&link-type=html"},"op":29,"ar":4,"head":"§633a. Nondiscrimination on account of age in Federal Government employment","tname":"Labor","by":{"0":"passim, passim, 2, 3, 33, 3, 44, 45, 3, passim"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"op":11,"ar":2,"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"0":"passim"}},{"t":"usc","label":"42 U.S.C. § 2000e-3","url":"https://www.law.cornell.edu/uscode/text/42/2000e-3","subs":["(a)"],"by":{"0":"38"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(f)","(g)(2)(A)"],"by":{"0":"38, 38"}},{"t":"usc","label":"42 U.S.C. § 2000e-16","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16","subs":["(a)","(d)"],"ar":1,"by":{"0":"32, 38, 39, 38, 39, 31, 32"}},{"t":"law","label":"Pub. L. No. 95-454","url":"https://www.govinfo.gov/link/statute/92/1116","by":{"0":"34"}},{"t":"usc","label":"5 U.S.C. § 2301","url":"https://www.law.cornell.edu/uscode/text/5/2301","by":{"0":"3"}},{"t":"usc","label":"5 U.S.C. § 2302","url":"https://www.law.cornell.edu/uscode/text/5/2302","subs":["(a)(1)","(a)(2)(A)","(a)(2)(A)(xi)","(a)(2)(B)","(a)(2)(C)","(b)","(b)(9)"],"stext":{"head":"§2302. Prohibited personnel practices","paras":[[0,"(a)(1) For the purpose of this title, \"prohibited personnel practice\" means any action described in subsection (b)."],[0,"(2) For the purpose of this section—"],[1,"(A) \"personnel action\" means—"],[2,"(i) an appointment;"],[2,"(ii) a promotion;"],[2,"(iii) an action under chapter 75 of this title or other disciplinary or corrective action;"],[2,"(iv) a detail, transfer, or reassignment;"],[2,"(v) a reinstatement;"],[2,"(vi) a restoration;"],[2,"(vii) a reemployment;"],[2,"(viii) a performance evaluation under chapter 43 of this title or under title 38;"],[2,"(ix) a decision concerning pay, benefits, or awards, or concerning education or training if the education or training may reasonably be expected to lead to an appointment, promotion, performance evaluation, or other action described in this subparagraph;"],[2,"(x) a decision to order psychiatric testing or examination;"],[2,"(xi) the implementation or enforcement of any nondisclosure policy, form, or agreement; and"],[2,"(xii) any other significant change in duties, responsibilities, or working conditions;"],[1,"with respect to an employee in, or applicant for, a covered position in an agency, and in the case of an alleged prohibited personnel practice described in subsection (b)(8), an employee or applicant for employment in a Government corporation as defined in section 9101 of title 31;"],[1,"(B) \"covered position\" means, with respect to any personnel action, any position in the competitive service, a career appointee position in the Senior Executive Service, or a position in the excepted service, but does not include any position which is, prior to the personnel action—"],[2,"(i) excepted from the competitive service because of its confidential, policy-determining, policy-making, or policy-advocating character; or"],[2,"(ii) excluded from the coverage of this section by the President based on a determination by the President that it is necessary and warranted by conditions of good administration;"],[1,"(C) \"agency\" means an Executive agency and the Government Publishing Office, but does not include—"],[2,"(i) a Government corporation, except in the case of an alleged prohibited personnel practice described under subsection (b)(8) or section 2302(b)(9)(A)(i), (B), (C), or (D);"],[2,"(ii)(I) the Federal Bureau of Investigation, the Central Intelligence Agency, the Defense Intelligence Agency, the National Geospatial-Intelligence Agency, the National Security Agency, the Office of the Director of National Intelligence, and the National Reconnaissance Office; and"],[2,"(II) as determined by the President, any executive agency or unit thereof the principal function of which is the conduct of foreign intelligence or counterintelligence activities, provided that the determination be made prior to a personnel action; or"],[2,"(iii) the Government Accountability Office; and"],[1,"(D) \"disclosure\" means a formal or informal communication or transmission, but does not include a communication concerning policy decisions that lawfully exercise discretionary authority unless the employee or applicant providing the disclosure reasonably believes that the disclosure evidences—"],[2,"(i) any violation of any law, rule, or regulation; or"],[2,"(ii) gross mismanagement, a gross waste of funds, an abuse of authority, or a substantial and specific danger to public health or safety."],[0,"(b) Any employee who has authority to take, direct others to take, recommend, or approve any personnel action, shall not, with respect to such authority—"],[1,"(1) discriminate for or against any employee or applicant for employment—"],[2,"(A) on the basis of race, color, religion, sex, or national origin, as prohibited under section 717 of the Civil Rights Act of 1964 (42 U.S.C. 2000e–16);"],[2,"(B) on the basis of age, as prohibited under sections 12 and 15 of the Age Discrimination in Employment Act of 1967 (29 U.S.C. 631, 633a);"],[2,"(C) on the basis of sex, as prohibited under section 6(d) of the Fair Labor Standards Act of 1938 (29 U.S.C. 206(d));"],[2,"(D) on the basis of handicapping condition, as prohibited under section 501 of the Rehabilitation Act of 1973 (29 U.S.C. 791); or"],[2,"(E) on the basis of marital status or political affiliation, as prohibited under any law, rule, or regulation;"],[1,"(2) solicit or consider any recommendation or statement, oral or written, with respect to any individual who requests or is under consideration for any personnel action unless such recommendation or statement is based on the personal knowledge or records of the person furnishing it and consists of—"],[2,"(A) an evaluation of the work performance, ability, aptitude, or general qualifications of such individual; or"],[2,"(B) an evaluation of the character, loyalty, or suitability of such individual;"],[1,"(3) coerce the political activity of any person (including the providing of any political contribution or service), or take any action against any employee or applicant for employment as a reprisal for the refusal of any person to engage in such political activity;"],[1,"(4) deceive or willfully obstruct any person with respect to such person's right to compete for employment;"],[1,"(5) influence any person to withdraw from competition for any position for the purpose of improving or injuring the prospects of any other person for employment;"],[1,"(6) grant any preference or advantage not authorized by law, rule, or regulation to any employee or applicant for employment (including defining the scope or manner of competition or the requirements for any position) for the purpose of improving or injuring the prospects of any particular person for employment;"],[1,"(7) appoint, employ, promote, advance, or advocate for appointment, employment, promotion, or advancement, in or to a civilian position any individual who is a relative (as defined in section 3110(a)(3) of this title) of such employee if such position is in the agency in which such employee is serving as a public official (as defined in section 3110(a)(2) of this title) or over which such employee exercises jurisdiction or control as such an official;"],[1,"(8) take or fail to take, or threaten to take or fail to take, a personnel action with respect to any employee or applicant for employment because of—"],[2,"(A) any disclosure of information by an employee or applicant which the employee or applicant reasonably believes evidences—"],[3,"(i) any violation of any law, rule, or regulation, or"],[3,"(ii) gross mismanagement, a gross waste of funds, an abuse of authority, or a substantial and specific danger to public health or safety,"],[2,"if such disclosure is not specifically prohibited by law and if such information is not specifically required by Executive order to be kept secret in the interest of national defense or the conduct of foreign affairs;"],[2,"(B) any disclosure to the Special Counsel, or to the Inspector General of an agency or another employee designated by the head of the agency to receive such disclosures, of information which the employee or applicant reasonably believes evidences—"],[3,"(i) any violation (other than a violation of this section) of any law, rule, or regulation, or"],[3,"(ii) gross mismanagement, a gross waste of funds, an abuse of authority, or a substantial and specific danger to public health or safety; or"],[2,"(C) any disclosure to Congress (including any committee of Congress) by any employee of an agency or applicant for employment at an agency of information described in subparagraph (B) that is—"],[3,"(i) not classified; or"],[3,"(ii) if classified—"],[4,"(I) has been classified by the head of an agency that is not an element of the intelligence community (as defined by section 3 of the National Security Act of 1947 (50 U.S.C. 3003)); and"],[4,"(II) does not reveal intelligence sources and methods.1"],[1,"(9) take or fail to take, or threaten to take or fail to take, any personnel action against any employee or applicant for employment because of—"],[2,"(A) the exercise of any appeal, complaint, or grievance right granted by any law, rule, or regulation—"],[3,"(i) with regard to remedying a violation of paragraph (8); or"],[3,"(ii) other than with regard to remedying a violation of paragraph (8);"],[2,"(B) testifying for or otherwise lawfully assisting any individual in the exercise of any right referred to in subparagraph (A)(i) or (ii);"],[2,"(C) cooperating with or disclosing information to the Inspector General (or any other component responsible for internal investigation or review) of an agency, or the Special Counsel, in accordance with applicable provisions of law; or"],[2,"(D) refusing to obey an order that would require the individual to violate a law, rule, or regulation;"],[1,"(10) discriminate for or against any employee or applicant for employment on the basis of conduct which does not adversely affect the performance of the employee or applicant or the performance of others; except that nothing in this paragraph shall prohibit an agency from taking into account in determining suitability or fitness any conviction of the employee or applicant for any crime under the laws of any State, of the District of Columbia, or of the United States;"],[1,"(11)(A) knowingly take, recommend, or approve any personnel action if the taking of such action would violate a veterans' preference requirement; or"],[1,"(B) knowingly fail to take, recommend, or approve any personnel action if the failure to take such action would violate a veterans' preference requirement;"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/2302?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2302. Prohibited personnel practices","tname":"Government Organization and Employees","by":{"0":"3, 16, 34, 34, 3, 34, 3, 4, 34"}},{"t":"usc","label":"5 U.S.C. § 7512","url":"https://www.law.cornell.edu/uscode/text/5/7512","stext":{"head":"§7512. Actions covered","paras":[[0,"This subchapter applies to—"],[1,"(1) a removal;"],[1,"(2) a suspension for more than 14 days;"],[1,"(3) a reduction in grade;"],[1,"(4) a reduction in pay; and"],[1,"(5) a furlough of 30 days or less;"],[0,"but does not apply to—"],[1,"(A) a suspension or removal under section 7532 of this title,"],[1,"(B) a reduction-in-force action under section 3502 of this title,"],[1,"(C) the reduction in grade of a supervisor or manager who has not completed the probationary period under section 3321(a)(2) of this title if such reduction is to the grade held immediately before becoming such a supervisor or manager,"],[1,"(D) a reduction in grade or removal under section 4303 of this title,"],[1,"(E) an action initiated under section 1215 or 7521 of this title, or"],[1,"(F) a suitability action taken by the Office under regulations prescribed by the Office, subject to the rules prescribed by the President under this title for the administration of the competitive service."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/7512?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7512. Actions covered","tname":"Government Organization and Employees","by":{"0":"35"}},{"t":"usc","label":"5 U.S.C. § 7513","url":"https://www.law.cornell.edu/uscode/text/5/7513","subs":["(d)"],"by":{"0":"35"}},{"t":"usc","label":"5 U.S.C. § 7701","url":"https://www.law.cornell.edu/uscode/text/5/7701","subs":["(b)(2)","(g)"],"by":{"0":"35, 35, 35"}},{"t":"usc","label":"5 U.S.C. § 7702","url":"https://www.law.cornell.edu/uscode/text/5/7702","subs":["(a)(1)"],"by":{"0":"35"}},{"t":"usc","label":"5 U.S.C. § 7703","url":"https://www.law.cornell.edu/uscode/text/5/7703","subs":["(b)"],"by":{"0":"35"}},{"t":"usc","label":"2 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/2/1301","by":{"0":"36"}},{"t":"usc","label":"2 U.S.C. § 1311","url":"https://www.law.cornell.edu/uscode/text/2/1311","subs":["(a)(2)"],"stext":{"head":"§1311. Rights and protections under title VII of Civil Rights Act of 1964, Age Discrimination in Employment Act of 1967, Rehabilitation Act of 1973, and title I of Americans with Disabilities Act of 1990","paras":[[0,"(a) Discriminatory practices prohibited"],[0,"All personnel actions affecting covered employees shall be made free from any discrimination based on—"],[1,"(1) race, color, religion, sex, or national origin, within the meaning of section 703 of the Civil Rights Act of 1964 (42 U.S.C. 2000e–2);"],[1,"(2) age, within the meaning of section 15 of the Age Discrimination in Employment Act of 1967 (29 U.S.C. 633a); or"],[1,"(3) disability, within the meaning of section 501 of the Rehabilitation Act of 1973 (29 U.S.C. 791) and sections 102 through 104 of the Americans with Disabilities Act of 1990 (42 U.S.C. 12112–12114)."],[0,"(b) Remedy"],[0,"(1) Civil rights"],[1,"The remedy for a violation of subsection (a)(1) shall be—"],[2,"(A) such remedy as would be appropriate if awarded under section 706(g) of the Civil Rights Act of 1964 (42 U.S.C. 2000e–5(g)); and"],[2,"(B) such compensatory damages as would be appropriate if awarded under section 1981 of title 42, or as would be appropriate if awarded under sections 1981a(a)(1), 1981a(b)(2), and, irrespective of the size of the employing office, 1981a(b)(3)(D) of title 42."],[0,"(2) Age discrimination"],[1,"The remedy for a violation of subsection (a)(2) shall be—"],[2,"(A) such remedy as would be appropriate if awarded under section 15(c) of the Age Discrimination in Employment Act of 1967 (29 U.S.C. 633a(c)); and"],[2,"(B) such liquidated damages as would be appropriate if awarded under section 7(b) of such Act (29 U.S.C. 626(b))."],[1,"In addition, the waiver provisions of section 7(f) of such Act (29 U.S.C. 626(f)) shall apply to covered employees."],[0,"(3) Disabilities discrimination"],[1,"The remedy for a violation of subsection (a)(3) shall be—"],[2,"(A) such remedy as would be appropriate if awarded under section 505(a)(1) of the Rehabilitation Act of 1973 (29 U.S.C. 794a(a)(1)) or section 107(a) of the Americans with Disabilities Act of 1990 (42 U.S.C. 12117(a)); and"],[2,"(B) such compensatory damages as would be appropriate if awarded under sections 1981a(a)(2), 1981a(a)(3), 1981a(b)(2), and, irrespective of the size of the employing office, 1981a(b)(3)(D) of title 42."],[0,"(c) Omitted"],[0,"(d) Application to unpaid staff"],[0,"(1) In general"],[1,"Subsections (a) and (b) shall apply with respect to—"],[2,"(A) any staff member of an employing office who carries out official duties of the employing office but who is not paid by the employing office for carrying out such duties (referred to in this subsection as an \"unpaid staff member\"), including an intern, an individual detailed to an employing office, and an individual participating in a fellowship program, in the same manner and to the same extent as such subsections apply with respect to a covered employee; and"],[2,"(B) a former unpaid staff member, if the act that may be a violation of subsection (a) occurred during the service of the former unpaid staffer for the employing office."],[0,"(2) Rule of construction"],[1,"Nothing in paragraph (1) may be construed to extend liability for a violation of subsection (a) to an employing office on the basis of an action taken by any person who is not under the supervision or control of the employing office."],[0,"(3) Intern defined"],[1,"For purposes of this subsection, the term \"intern\" means an individual who performs service for an employing office which is uncompensated by the United States to earn credit awarded by an educational institution or to learn a trade or occupation, and includes any individual participating in a page program operated by any House of Congress."],[0,"(e) Effective date"],[0,"This section shall take effect 1 year after January 23, 1995."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/2/1311?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1311. Rights and protections under title VII of Civil Rights Act of 1964, Age Discrimination in Employment Act of 1967, Rehabilitation Act of 1973, and title I of Americans with Disabilities Act of 1990","tname":"The Congress","by":{"0":"36"}},{"t":"usc","label":"2 U.S.C. § 1317","url":"https://www.law.cornell.edu/uscode/text/2/1317","subs":["(a)"],"stext":{"head":"§1317. Prohibition of intimidation or reprisal","paras":[[0,"(a) In general"],[0,"It shall be unlawful for an employing office to intimidate, take reprisal against, or otherwise discriminate against, any covered employee because the covered employee has opposed any practice made unlawful by this chapter, or because the covered employee has initiated proceedings, made a charge, or testified, assisted, or participated in any manner in a hearing or other proceeding under this chapter."],[0,"(b) Remedy"],[0,"The remedy available for a violation of subsection (a) shall be such legal or equitable remedy as may be appropriate to redress a violation of subsection (a)."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/2/1317?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1317. Prohibition of intimidation or reprisal","tname":"The Congress","by":{"0":"36"}},{"t":"usc","label":"20 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/20/1681","subs":["(a)"],"stext":{"head":"§1681. Sex","paras":[[0,"(a) Prohibition against discrimination; exceptions"],[0,"No person in the United States shall, on the basis of sex, be excluded from participation in, be denied the benefits of, or be subjected to discrimination under any education program or activity receiving Federal financial assistance, except that:"],[0,"(1) Classes of educational institutions subject to prohibition"],[1,"in regard to admissions to educational institutions, this section shall apply only to institutions of vocational education, professional education, and graduate higher education, and to public institutions of undergraduate higher education;"],[0,"(2) Educational institutions commencing planned change in admissions"],[1,"in regard to admissions to educational institutions, this section shall not apply (A) for one year from June 23, 1972, nor for six years after June 23, 1972, in the case of an educational institution which has begun the process of changing from being an institution which admits only students of one sex to being an institution which admits students of both sexes, but only if it is carrying out a plan for such a change which is approved by the Secretary of Education or (B) for seven years from the date an educational institution begins the process of changing from being an institution which admits only students of only one sex to being an institution which admits students of both sexes, but only if it is carrying out a plan for such a change which is approved by the Secretary of Education, whichever is the later;"],[0,"(3) Educational institutions of religious organizations with contrary religious tenets"],[1,"this section shall not apply to an educational institution which is controlled by a religious organization if the application of this subsection would not be consistent with the religious tenets of such organization;"],[0,"(4) Educational institutions training individuals for military services or merchant marine"],[1,"this section shall not apply to an educational institution whose primary purpose is the training of individuals for the military services of the United States, or the merchant marine;"],[0,"(5) Public educational institutions with traditional and continuing admissions policy"],[1,"in regard to admissions this section shall not apply to any public institution of undergraduate higher education which is an institution that traditionally and continually from its establishment has had a policy of admitting only students of one sex;"],[0,"(6) Social fraternities or sororities; voluntary youth service organizations"],[1,"this section shall not apply to membership practices—"],[2,"(A) of a social fraternity or social sorority which is exempt from taxation under section 501(a) of title 26, the active membership of which consists primarily of students in attendance at an institution of higher education, or"],[2,"(B) of the Young Men's Christian Association, Young Women's Christian Association, Girl Scouts, Boy Scouts, Camp Fire Girls, and voluntary youth service organizations which are so exempt, the membership of which has traditionally been limited to persons of one sex and principally to persons of less than nineteen years of age;"],[0,"(7) Boy or Girl conferences"],[1,"this section shall not apply to—"],[2,"(A) any program or activity of the American Legion undertaken in connection with the organization or operation of any Boys State conference, Boys Nation conference, Girls State conference, or Girls Nation conference; or"],[2,"(B) any program or activity of any secondary school or educational institution specifically for—"],[3,"(i) the promotion of any Boys State conference, Boys Nation conference, Girls State conference, or Girls Nation conference; or"],[3,"(ii) the selection of students to attend any such conference;"],[0,"(8) Father-son or mother-daughter activities at educational institutions"],[1,"this section shall not preclude father-son or mother-daughter activities at an educational institution, but if such activities are provided for students of one sex, opportunities for reasonably comparable activities shall be provided for students of the other sex; and"],[0,"(9) Institution of higher education scholarship awards in \"beauty\" pageants"],[1,"this section shall not apply with respect to any scholarship or other financial assistance awarded by an institution of higher education to any individual because such individual has received such award in any pageant in which the attainment of such award is based upon a combination of factors related to the personal appearance, poise, and talent of such individual and in which participation is limited to individuals of one sex only, so long as such pageant is in compliance with other nondiscrimination provisions of Federal law."],[0,"(b) Preferential or disparate treatment because of imbalance in participation or receipt of Federal benefits; statistical evidence of imbalance"],[0,"Nothing contained in subsection (a) of this section shall be interpreted to require any educational institution to grant preferential or disparate treatment to the members of one sex on account of an imbalance which may exist with respect to the total number or percentage of persons of that sex participating in or receiving the benefits of any federally supported program or activity, in comparison with the total number or percentage of persons of that sex in any community, State, section, or other area: Provided, That this subsection shall not be construed to prevent the consideration in any hearing or proceeding under this chapter of statistical evidence tending to show that such an imbalance exists with respect to the participation in, or receipt of the benefits of, any such program or activity by the members of one sex."],[0,"(c) \"Educational institution\" defined"],[0,"For purposes of this chapter an educational institution means any public or private preschool, elementary, or secondary school, or any institution of vocational, professional, or higher education, except that in the case of an educational institution composed of more than one school, college, or department which are administratively separate units, such term means each such school, college, or department."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/20/1681?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1681. Sex","tname":"Education","by":{"0":"passim, 19"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"0":"26"}},{"t":"usc","label":"29 U.S.C. § 203","url":"https://www.law.cornell.edu/uscode/text/29/203","subs":["(e)(2)"],"by":{"0":"26"}},{"t":"usc","label":"29 U.S.C. § 215","url":"https://www.law.cornell.edu/uscode/text/29/215","subs":["(a)(3)"],"op":1,"by":{"0":"26"}},{"t":"law","label":"Pub. L. No. 93-259","url":"https://www.govinfo.gov/link/statute/88/55","by":{"0":"26"}},{"t":"usc","label":"39 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/39/101","by":{"0":"6"}},{"t":"usc","label":"39 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/39/401","subs":["(1)"],"stext":{"head":"§401. General powers of the Postal Service","paras":[[0,"Subject to the provisions of section 404a, the Postal Service shall have the following general powers:"],[1,"(1) to sue and be sued in its official name;"],[1,"(2) to adopt, amend, and repeal such rules and regulations, not inconsistent with this title, as may be necessary in the execution of its functions under this title and such other functions as may be assigned to the Postal Service under any provisions of law outside of this title;"],[1,"(3) to enter into and perform contracts, execute instruments, and determine the character of, and necessity for, its expenditures;"],[1,"(4) to determine and keep its own system of accounts and the forms and contents of its contracts and other business documents, except as otherwise provided in this title;"],[1,"(5) to acquire, in any lawful manner, such personal or real property, or any interest therein, as it deems necessary or convenient in the transaction of its business; to hold, maintain, sell, lease, or otherwise dispose of such property or any interest therein; and to provide services in connection therewith and charges therefor;"],[1,"(6) to construct, operate, lease, and maintain buildings, facilities, equipment, and other improvements on any property owned or controlled by it, including, without limitation, any property or interest therein transferred to it under section 2002 of this title;"],[1,"(7) to accept gifts or donations of services or property, real or personal, as it deems, necessary or convenient in the transaction of its business;"],[1,"(8) to settle and compromise claims by or against it;"],[1,"(9) to exercise, in the name of the United States, the right of eminent domain for the furtherance of its official purposes; and to have the priority of the United States with respect to the payment of debts out of bankrupt, insolvent, and decedents' estates; and"],[1,"(10) to have all other powers incidental, necessary, or appropriate to the carrying on of its functions or the exercise of its specific powers."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/39/401?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§401. General powers of the Postal Service","tname":"Postal Service","by":{"0":"46"}},{"t":"usc","label":"39 U.S.C. § 410","url":"https://www.law.cornell.edu/uscode/text/39/410","subs":["(a)"],"by":{"0":"4, 36"}},{"t":"usc","label":"39 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/39/1001","subs":["(b)"],"by":{"0":"4, 36, 4, 36"}},{"t":"usc","label":"39 U.S.C. § 1206","url":"https://www.law.cornell.edu/uscode/text/39/1206","subs":["(b)"],"by":{"0":"4, 36"}},{"t":"usc","label":"39 U.S.C. § 1209","url":"https://www.law.cornell.edu/uscode/text/39/1209","subs":["(a)"],"by":{"0":"4, 36"}},{"t":"usc","label":"3 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/3/401","by":{"0":"36"}},{"t":"usc","label":"3 U.S.C. § 411","url":"https://www.law.cornell.edu/uscode/text/3/411","subs":["(a)(2)"],"stext":{"head":"§411. Rights and protections under title VII of the Civil Rights Act of 1964, the Age Discrimination in Employment Act of 1967, the Rehabilitation Act of 1973, and title I of the Americans with Disabilities Act of 1990","paras":[[0,"(a) Discriminatory Practices Prohibited.—All personnel actions affecting covered employees shall be made free from any discrimination based on—"],[1,"(1) race, color, religion, sex, or national origin, within the meaning of section 703 of the Civil Rights Act of 1964;"],[1,"(2) age, within the meaning of section 15 of the Age Discrimination in Employment Act of 1967; or"],[1,"(3) disability, within the meaning of section 501 of the Rehabilitation Act of 1973 and sections 102 through 104 of the Americans with Disabilities Act of 1990."],[0,"(b) Remedy.—"],[1,"(1) Civil rights.—The remedy for a violation of subsection (a)(1) shall be—"],[2,"(A) such damages as would be appropriate if awarded under section 706(g) of the Civil Rights Act of 1964; and"],[2,"(B) such compensatory damages as would be appropriate if awarded under section 1977 of the Revised Statutes, or as would be appropriate if awarded under sections 1977A(a)(1), 1977A(b)(2), and, irrespective of the size of the employing office, 1977A(b)(3)(D) of the Revised Statutes."],[1,"(2) Age discrimination.—The remedy for a violation of subsection (a)(2) shall be—"],[2,"(A) such damages as would be appropriate if awarded under section 15(c) of the Age Discrimination in Employment Act of 1967; and"],[2,"(B) such liquidated damages as would be appropriate if awarded under section 7(b) of such Act."],[1,"In addition, the waiver provisions of section 7(f) of such Act shall apply to covered employees."],[1,"(3) Disabilities discrimination.—The remedy for a violation of subsection (a)(3) shall be—"],[2,"(A) such damages as would be appropriate if awarded under section 505(a)(1) of the Rehabilitation Act of 1973 or section 107(a) of the Americans with Disabilities Act of 1990; and"],[2,"(B) such compensatory damages as would be appropriate if awarded under sections 1977A(a)(2), 1977A(a)(3), 1977A(b)(2), and, irrespective of the size of the employing office, 1977A(b)(3)(D) of the Revised Statutes."],[0,"(c) Definitions.—Except as otherwise specifically provided in this section, as used in this section:"],[1,"(1) Covered employee.—The term \"covered employee\" means any employee of a unit of the executive branch, including the Executive Office of the President, whether appointed by the President or by any other appointing authority in the executive branch, who is not otherwise entitled to bring an action under any of the statutes referred to in subsection (a), but does not include any individual—"],[2,"(A) whose appointment is made by and with the advice and consent of the Senate;"],[2,"(B) who is appointed to an advisory committee, as defined in section 1001 of title 5; or"],[2,"(C) who is a member of the uniformed services."],[1,"(2) Employing office.—The term \"employing office\", with respect to a covered employee, means the office, agency, or other entity in which the covered employee is employed (or sought employment or was employed in the case of an applicant or former employee, respectively)."],[0,"(d) Regulations To Implement Section.—"],[1,"(1) In general.—The President, or the designee of the President, shall issue regulations to implement paragraphs (1) and (3) of subsection (a) and paragraphs (1) and (3) of subsection (b)."],[1,"(2) Agency regulations.—The regulations issued under paragraph (1) shall be the same as substantive regulations promulgated by the appropriate officer of an executive agency to implement the statutory provisions referred to in paragraphs (1) and (3) of subsection (a) and paragraphs (1) and (3) of subsection (b)—"],[2,"(A) except to the extent that the President or designee may determine, for good cause shown and stated together with the regulation, that a modification of such regulations would be more effective for the implementation of the rights and protections under this section; and"],[2,"(B) except that the President or designee may, at the discretion of the President or designee, issue regulations to implement a provision of section 717 of the Civil Rights Act of 1964 or section 501 of the Rehabilitation Act of 1973 that applies to employees in the executive branch of the Federal Government in lieu of an analogous statutory provision referred to in paragraph (1) or (3) of subsection (a) or paragraph (1) or (3) of subsection (b), if the issuance of such regulations—"],[3,"(i) would be equally effective for the implementation of the rights and protections under this section; and"],[3,"(ii) would promote uniformity in the application of Federal law to employees in the executive branch of the Federal Government."],[0,"(e) Applicability.—Subsections (a) through (c), and section 417 (to the extent that it relates to any matter under this section), shall apply with respect to violations occurring on or after the effective date of this chapter."],[0,"(f) Effective Date.—This section shall take effect on October 1, 1997."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/3/411?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§411. Rights and protections under title VII of the Civil Rights Act of 1964, the Age Discrimination in Employment Act of 1967, the Rehabilitation Act of 1973, and title I of the Americans with Disabilities Act of 1990","tname":"The President","by":{"0":"36"}},{"t":"usc","label":"3 U.S.C. § 417","url":"https://www.law.cornell.edu/uscode/text/3/417","subs":["(a)"],"stext":{"head":"§417. Prohibition of intimidation or reprisal","paras":[[0,"(a) In General.—It shall be unlawful for an employing office to intimidate, take reprisal against, or otherwise discriminate against, any covered employee because the covered employee has opposed any practice made unlawful by this chapter, or because the covered employee has initiated proceedings, made a charge, or testified, assisted, or participated in any manner in a hearing or other proceeding under this chapter."],[0,"(b) Remedy.—A violation of subsection (a) may be remedied by any legal remedy available to redress the practice opposed by the covered employee or other violation of law as to which the covered employee initiated proceedings, made a charge, or engaged in other conduct protected under subsection (a)."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/3/417?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§417. Prohibition of intimidation or reprisal","tname":"The President","by":{"0":"36"}},{"t":"usc","label":"5 U.S.C. § 1214","url":"https://www.law.cornell.edu/uscode/text/5/1214","subs":["(a)(1)(A)","(b)(2)(B)","(b)(2)(C)","(b)(4)","(c)"],"by":{"0":"35, 35, 35, 35, 35"}},{"t":"usc","label":"5 U.S.C. § 1215","url":"https://www.law.cornell.edu/uscode/text/5/1215","op":1,"by":{"0":"35"}},{"t":"usc","label":"5 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/5/1301","subs":["(1970)"],"by":{"0":"30"}},{"t":"usc","label":"5 U.S.C. § 3301","url":"https://www.law.cornell.edu/uscode/text/5/3301","subs":["(1970)"],"by":{"0":"30"}},{"t":"usc","label":"5 U.S.C. § 3302","url":"https://www.law.cornell.edu/uscode/text/5/3302","subs":["(1970)"],"by":{"0":"30"}},{"t":"usc","label":"5 U.S.C. § 7151","url":"https://www.law.cornell.edu/uscode/text/5/7151","subs":["(1970)"],"by":{"0":"30"}},{"t":"usc","label":"28 U.S.C. § 1505","url":"https://www.law.cornell.edu/uscode/text/28/1505","by":{"0":"45"}},{"t":"usc","label":"42 U.S.C. § 1981","url":"https://www.law.cornell.edu/uscode/text/42/1981","stext":{"head":"§1981. Equal rights under the law","paras":[[0,"(a) Statement of equal rights"],[0,"All persons within the jurisdiction of the United States shall have the same right in every State and Territory to make and enforce contracts, to sue, be parties, give evidence, and to the full and equal benefit of all laws and proceedings for the security of persons and property as is enjoyed by white citizens, and shall be subject to like punishment, pains, penalties, taxes, licenses, and exactions of every kind, and to no other."],[0,"(b) \"Make and enforce contracts\" defined"],[0,"For purposes of this section, the term \"make and enforce contracts\" includes the making, performance, modification, and termination of contracts, and the enjoyment of all benefits, privileges, terms, and conditions of the contractual relationship."],[0,"(c) Protection against impairment"],[0,"The rights protected by this section are protected against impairment by nongovernmental discrimination and impairment under color of State law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1981?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":1,"head":"§1981. Equal rights under the law","tname":"The Public Health and Welfare","by":{"0":"21, 22"}},{"t":"usc","label":"42 U.S.C. § 1982","url":"https://www.law.cornell.edu/uscode/text/42/1982","stext":{"head":"§1982. Property rights of citizens","paras":[[0,"All citizens of the United States shall have the same right, in every State and Territory, as is enjoyed by white citizens thereof to inherit, purchase, lease, sell, hold, and convey real and personal property."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1982?type=usc&year=mostrecent&link-type=html"},"op":8,"head":"§1982. Property rights of citizens","tname":"The Public Health and Welfare","by":{"0":"20, 22, 24"}},{"t":"reg","label":"3 C.F.R. pt. 520","url":"https://www.ecfr.gov/current/title-3/part-520","by":{"0":"30"}},{"t":"reg","label":"3 C.F.R. pt. 803","url":"https://www.ecfr.gov/current/title-3/part-803","by":{"0":"30"}},{"t":"reg","label":"37 Fed. Reg. 22,717","url":"https://www.govinfo.gov/link/fr/37/22717","by":{"0":"32"}},{"t":"reg","label":"39 Fed. Reg. 24,351","url":"https://www.govinfo.gov/link/fr/39/24351","by":{"0":"33, 34"}}]};